create table if not exists aios_missions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references aios_organizations(id) on delete cascade,title text not null,objective text not null,status text not null default 'queued',created_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,metadata jsonb not null default '{}'::jsonb);
create table if not exists aios_tool_invocations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references aios_organizations(id) on delete cascade,agent_id uuid references aios_agents(id),task_id uuid references aios_tasks(id),tool_name text not null,arguments jsonb not null default '{}'::jsonb,status text not null default 'requested',result jsonb,risk_level text not null default 'low',approval_id uuid references aios_approvals(id),created_at timestamptz not null default now(),completed_at timestamptz);
create index if not exists idx_aios_missions_org_created on aios_missions(organization_id,created_at desc);
create index if not exists idx_aios_tools_task_created on aios_tool_invocations(task_id,created_at desc);
